//! `features codeowners` run on `examples/codeowners-generation`, writing to a
//! temporary copy of its CODEOWNERS file

use std::path::PathBuf;
use std::process::Command;

fn example_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../examples/codeowners-generation")
}

/// Run `features codeowners` from the example folder, writing to a copy of its
/// CODEOWNERS file, and return the generated file
fn generate(extra_args: &[&str]) -> String {
    let dir = tempfile::tempdir().unwrap();
    let output_path = dir.path().join("CODEOWNERS");
    std::fs::copy(example_path().join("CODEOWNERS"), &output_path).unwrap();

    let output = Command::new(env!("CARGO_BIN_EXE_features"))
        .current_dir(example_path())
        .args(["codeowners", "src", "--project-dir", ".", "--skip-changes"])
        .arg("--codeowners-path")
        .arg(&output_path)
        .args(extra_args)
        .output()
        .expect("failed to run features");
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    std::fs::read_to_string(&output_path).unwrap()
}

#[test]
fn test_generated_section_replaces_stale_lines_and_keeps_custom_rules() {
    assert_eq!(
        generate(&[]),
        "\
# Hand-written rules, kept when the file is regenerated
* @acme/maintainers

# ==== GENERATED BY FEATURES-CLI ====
/src/features/growth @acme/growth
/src/features/legacy @Unknown
/src/features/platform @platform-team
/src/features/platform/features/audit @security-team
# ==== END SECTION GENERATED BY FEATURES-CLI ====

# Hand-written rules after the generated section are kept too
/docs/ @acme/docs
"
    );
}

#[test]
fn test_nested_feature_with_parent_owner_has_no_line() {
    let content = generate(&[]);
    assert!(!content.contains("features/auth"), "{content}");
    assert!(!content.contains("removed"), "{content}");
}

#[test]
fn test_custom_prefix() {
    let content = generate(&["--codeowners-prefix", "team:"]);
    assert!(
        content.contains("/src/features/platform team:platform-team\n"),
        "{content}"
    );
    assert!(
        content.contains("/src/features/legacy team:Unknown\n"),
        "{content}"
    );
    // Hand-written rules keep their own owners
    assert!(content.contains("* @acme/maintainers\n"), "{content}");
}

#[test]
fn test_empty_prefix_keeps_owners_as_written() {
    let content = generate(&["--codeowners-prefix", ""]);
    assert!(
        content.contains("/src/features/platform platform-team\n"),
        "{content}"
    );
    assert!(
        content.contains("/src/features/growth @acme/growth\n"),
        "{content}"
    );
}

#[test]
fn test_new_file_has_only_the_generated_section() {
    let dir = tempfile::tempdir().unwrap();
    let output_path = dir.path().join("nested").join("OWNERS");
    std::fs::create_dir_all(output_path.parent().unwrap()).unwrap();

    let output = Command::new(env!("CARGO_BIN_EXE_features"))
        .current_dir(example_path())
        .args(["codeowners", "src", "--project-dir", ".", "--skip-changes"])
        .arg("--codeowners-path")
        .arg(&output_path)
        .output()
        .unwrap();
    assert!(output.status.success());
    let content = std::fs::read_to_string(&output_path).unwrap();
    assert!(content.starts_with("# ==== GENERATED BY FEATURES-CLI ====\n"));
    assert!(content.ends_with("# ==== END SECTION GENERATED BY FEATURES-CLI ====\n"));
}
